const $=id=>document.getElementById(id);
function render(items){
 const ul=$('list');ul.textContent='';
 $('empty').hidden=items.length>0;
 for(const a of items){
  const li=document.createElement('li');li.setAttribute('data-hook','answer');
  const n=document.createElement('strong');n.textContent=a.name;
  const p=document.createElement('span');p.textContent='People: '+a.people;
  const al=document.createElement('span');al.textContent='Food allergies: '+(a.allergies||'none');
  li.append(n,p,al);ul.append(li);
 }
}
async function load(){
 const r=await tessera.call('data.read',{});
 render(r.data.answers||[]);
}
$('send').addEventListener('click',async()=>{
 $('status').textContent='';
 const name=$('name').value.trim(),people=$('people').value.trim(),al=$('allergies').value.trim();
 const miss=[];
 if(!name)miss.push('Name');
 if(!people||Number(people)<1)miss.push('How many people');
 if(miss.length){$('err').textContent='Please fill in: '+miss.join(', ')+'.';return}
 $('err').textContent='';
 try{
  await tessera.call('data.patch',{operations:[{op:'add',collection:'answers',record:{name:name,people:Number(people),allergies:al}}]});
  $('name').value='';$('people').value='';$('allergies').value='';
  $('status').textContent='Answer sent. Thank you!';
  await load();
 }catch(e){$('err').textContent='The answer could not be saved. Please try again.'}
});
load();

